"""Dependency-free, import-safe resources for the local operator panel."""

from __future__ import annotations

from types import MappingProxyType


SECURITY_HEADERS = MappingProxyType({"Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer", "X-Frame-Options": "DENY"})
CONTENT_SECURITY_POLICY = ("default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")

OPERATOR_HTML = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Browser Agent Operator</title><link rel="stylesheet" href="/operator.css"></head><body><main><header><div><p class="eyebrow">LOCAL OPERATOR</p><h1>Browser Agent</h1></div><button id="toggle-diagnostics" class="secondary compact" type="button" aria-controls="diagnostics-panel" aria-expanded="true">Hide diagnostics</button></header><div id="columns" class="columns"><section class="column conversation-column" aria-labelledby="conversation-title"><h2 id="conversation-title">Conversation</h2><div class="start-card"><label for="start-url">Start URL</label><input id="start-url" type="url" required autocomplete="url"><label for="task">Task</label><textarea id="task" required rows="3"></textarea><button id="start" type="button">Start</button><button id="cancel" class="danger" type="button" disabled>Cancel</button></div><div id="conversation" aria-live="polite"></div><div id="interaction" hidden><p id="question" hidden></p><div id="user-panel" hidden><label for="user-response">Response</label><textarea id="user-response" rows="3"></textarea><button id="send-response" type="button">Send</button></div><div id="confirmation-panel" hidden><button id="approve" type="button">Approve</button><button id="reject" class="secondary" type="button">Reject</button></div><form id="secret-panel" hidden autocomplete="on"><div id="secret-fields"></div><button id="send-secret" type="submit">Submit securely</button></form></div><div id="downloads-wrap" hidden><h3>Downloads</h3><ul id="downloads"></ul></div></section><aside id="diagnostics-panel" class="column diagnostics" aria-labelledby="diagnostics-title"><div class="diagnostics-heading"><h2 id="diagnostics-title">Diagnostics</h2><button id="diagnostics-follow" class="secondary compact" type="button" hidden>Jump to latest</button></div><div class="run-head"><span id="run-id">None</span><span id="status">idle</span></div><div id="activity">Ready.</div><div id="error" role="alert"></div><ol id="diagnostics" aria-live="polite"></ol><ol id="timeline" hidden></ol><p id="timeline-empty" hidden></p><div id="result-wrap" hidden><pre id="result"></pre></div></aside></div></main><script src="/operator.js" defer></script></body></html>"""

OPERATOR_JAVASCRIPT = r"""'use strict';
(() => {
  const byId=id=>document.getElementById(id), terminal=new Set(['finished','failed','cancelled','step_limit_reached','decision_source_exhausted']);
  const state={runId:null,generation:0,latestVersion:-1,timer:null,pollPending:false,submitPending:false,secretInteractionId:null,userInteractionId:null,active:false,seenAudits:new Set(),seenFiles:new Set(),finalShown:false,diagnosticsFollow:true};
  const requestId=()=>globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;
  const clearSecrets=()=>byId('secret-fields').querySelectorAll('input').forEach(input=>{ input.value = ''; });
  const add=(container,kind,text)=>{const node=document.createElement('div');node.className=kind;node.textContent=text;container.append(node);return node;};
  const message=(role,text)=>add(byId('conversation'),`message ${role}`,text);
  const scrollDiagnosticsToLatest=()=>{const log=byId('diagnostics');log.scrollTop=log.scrollHeight;};
  const diagnostic=(layer,fields={})=>{const item=document.createElement('li'), parts=[new Date().toISOString(),fields.severity||'INFO',layer];['method','endpoint','status','contentType','length','duration','code','message','parseError','errorType','runStatus','version','audit'].forEach(key=>{if(fields[key]!==undefined&&fields[key]!==null&&fields[key]!=='')parts.push(`${key}: ${fields[key]}`);});item.textContent=parts.join(' | ');byId('diagnostics').append(item);if(state.diagnosticsFollow)scrollDiagnosticsToLatest();};
  const setDiagnosticsOpen=open=>{byId('diagnostics-panel').hidden=!open;byId('columns').classList.toggle('diagnostics-closed',!open);byId('toggle-diagnostics').textContent=open?'Hide diagnostics':'Show diagnostics';byId('toggle-diagnostics').setAttribute('aria-expanded',String(open));if(open&&state.diagnosticsFollow)scrollDiagnosticsToLatest();};
  const resetDiagnostics=()=>{state.diagnosticsFollow=true;byId('diagnostics-follow').hidden=true;setDiagnosticsOpen(true);byId('diagnostics').scrollTop=0;};
  const showError=text=>{byId('error').textContent=text||'';};
  async function api(path,options){const method=options&&options.method?options.method:'GET',started=Date.now();let response;try{response=await fetch(path,{credentials:'same-origin',...(options||{})});}catch(e){diagnostic('Network',{severity:'ERROR',method,endpoint:path,duration:Date.now()-started,message:e&&e.name?e.name:'FetchError'});throw new Error('Network request failed.');}const raw=await response.text(),contentType=response.headers&&response.headers.get?response.headers.get('Content-Type')||'':'';let body=null;if(raw.length){try{body=JSON.parse(raw);}catch(e){diagnostic('HTTP',{severity:'ERROR',method,endpoint:path,status:response.status,contentType,length:raw.length,duration:Date.now()-started,parseError:e.name});throw new Error('The server returned an unreadable response.');}}const envelope=body&&body.error&&typeof body.error==='object'?body.error:null;diagnostic('HTTP',{severity:response.ok?'INFO':'ERROR',method,endpoint:path,status:response.status,contentType,length:raw.length,duration:Date.now()-started,code:envelope&&envelope.code,message:envelope&&envelope.message});if(!response.ok)throw new Error(envelope&&envelope.message?envelope.message:'Request failed.');return body;}
  const validString=(v,n)=>typeof v==='string'&&v.trim()&&v.length<=n&&!/[\p{Cc}\p{Cf}]/u.test(v), positive=v=>Number.isSafeInteger(v)&&v>0;
  function renderAudit(snapshot){const kinds=new Set(['system','tool','user_input','confirmation','secret']),statuses=new Set(['info','success','pending','approved','rejected','failed','cancelled']);(Array.isArray(snapshot.audit_events)?snapshot.audit_events:[]).forEach(e=>{if(!e||typeof e!=='object'||Array.isArray(e)||!positive(e.sequence)||!validString(e.kind,50)||!kinds.has(e.kind)||!validString(e.status,50)||!statuses.has(e.status)||!validString(e.summary,200))return;if(e.tool_name!=null&&!validString(e.tool_name,100)||e.step_number!=null&&!positive(e.step_number)||e.replay_of_step_number!=null&&!positive(e.replay_of_step_number))return;const key=String(e.sequence);if(state.seenAudits.has(key))return;state.seenAudits.add(key);diagnostic('Audit',{audit:`sequence ${e.sequence}; kind ${e.kind}; status ${e.status}; summary ${e.summary}${e.tool_name?`; tool ${e.tool_name}`:''}${e.step_number?`; step ${e.step_number}`:''}`});});}
  function renderDownloads(snapshot){(Array.isArray(snapshot.files)?snapshot.files:[]).forEach(file=>{if(!file||state.seenFiles.has(file.file_id))return;state.seenFiles.add(file.file_id);const item=document.createElement('li'),title=document.createElement('span'),link=document.createElement('a');title.textContent=`${file.filename} (${file.size} bytes) `;link.textContent='Download';link.href=`runs/${encodeURIComponent(snapshot.run_id)}/files/${encodeURIComponent(file.file_id)}`;item.append(title,link);byId('downloads').append(item);});byId('downloads-wrap').hidden=state.seenFiles.size===0;}
  function renderSecrets(snapshot){const box=byId('secret-fields');box.replaceChildren();(snapshot.secret_fields||[]).forEach(field=>{const label=document.createElement('label'),input=document.createElement('input');label.textContent=field==='otp'?'One-time code':field[0].toUpperCase()+field.slice(1);input.name=field;input.required=true;input.type=field==='username'?'text':'password';input.autocomplete=field==='username'?'username':field==='password'?'current-password':'one-time-code';label.append(input);box.append(label);});}
  function current(s,x){return state.runId===s.runId&&state.generation===s.generation&&x.run_id===s.runId&&Number.isInteger(x.version)&&x.version>state.latestVersion;}
  function render(snapshot,selection){if(!current(selection,snapshot))return false;state.latestVersion=snapshot.version;byId('run-id').textContent=snapshot.run_id;byId('status').textContent=snapshot.status;byId('activity').textContent=`${snapshot.status} · ${snapshot.step_count} steps`;diagnostic('Snapshot',{runStatus:snapshot.status,version:snapshot.version,errorType:snapshot.error&&snapshot.error.type,message:snapshot.error&&snapshot.error.message});showError(snapshot.error?snapshot.error.message:'');const waiting=snapshot.status.startsWith('awaiting_');byId('interaction').hidden=!waiting;byId('interaction').dataset.interactionId=snapshot.interaction_id||'';byId('user-panel').hidden=snapshot.status!=='awaiting_user';byId('confirmation-panel').hidden=snapshot.status!=='awaiting_confirmation';byId('secret-panel').hidden=snapshot.status!=='awaiting_secret';if(waiting&&snapshot.question&&byId('interaction').dataset.renderedId!==snapshot.interaction_id){message('agent',snapshot.question);byId('interaction').dataset.renderedId=snapshot.interaction_id;}if(snapshot.status==='awaiting_user'){if(state.userInteractionId!==snapshot.interaction_id)byId('user-response').value='';state.userInteractionId=snapshot.interaction_id;}else{byId('user-response').value='';state.userInteractionId=null;}if(snapshot.status==='awaiting_secret'){if(state.secretInteractionId!==snapshot.interaction_id){clearSecrets();renderSecrets(snapshot);state.secretInteractionId=snapshot.interaction_id;}}else{clearSecrets();state.secretInteractionId=null;}state.active=!terminal.has(snapshot.status);byId('cancel').disabled=!state.active;byId('start').disabled=state.active;if(snapshot.final_result!=null&&!state.finalShown){message('agent',snapshot.final_result);state.finalShown=true;}renderAudit(snapshot);renderDownloads(snapshot);if(!state.active&&state.timer){clearInterval(state.timer);state.timer=null;}return true;}
  async function poll(){if (!state.runId || state.pollPending || state.submitPending)return;const selection={runId:state.runId,generation:state.generation};state.pollPending=true;try{render(await api(`runs/${encodeURIComponent(selection.runId)}`),selection);}catch(e){if(state.runId===selection.runId&&state.generation===selection.generation)showError(e.message);}finally{state.pollPending=false;}}
  function startPolling(){if(state.timer)clearInterval(state.timer);state.timer=setInterval(poll, 750);poll();}
  async function submitInteraction(factory,label){if(state.submitPending||!state.runId)return;const selection={runId:state.runId,generation:state.generation},interactionId=byId('interaction').dataset.interactionId;if(!interactionId)return;state.submitPending=true;document.querySelectorAll('#interaction button').forEach(b=>{b.disabled=true;});try{const payload=factory(interactionId);clearSecrets();const snapshot=await api(`runs/${encodeURIComponent(selection.runId)}/responses`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(render(snapshot,selection)){message('user',label);if(state.active)startPolling();}}catch(e){if(state.runId===selection.runId&&state.generation===selection.generation)showError(e.message);}finally{clearSecrets();state.submitPending=false;document.querySelectorAll('#interaction button').forEach(b=>{b.disabled=false;});}}
  byId('start').addEventListener('click',async()=>{if(state.submitPending)return;if(state.active){showError('Cancel or wait for the active run to finish before starting another.');return;}state.submitPending=true;try{const task=byId('task').value,snapshot=await api('runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start_url:byId('start-url').value,task})});state.generation++;state.runId=snapshot.run_id;state.latestVersion=-1;state.userInteractionId=null;state.secretInteractionId=null;state.seenAudits.clear();state.seenFiles.clear();state.finalShown=false;byId('conversation').replaceChildren();byId('diagnostics').replaceChildren();resetDiagnostics();byId('downloads').replaceChildren();byId('downloads-wrap').hidden=true;byId('interaction').dataset.renderedId='';showError('');message('user',task);const selection={runId:state.runId,generation:state.generation};render(snapshot,selection);if(state.active)startPolling();}catch(e){showError(e.message);}finally{state.submitPending=false;}});
  const sendUserResponse=()=>{const text=byId('user-response').value;if(state.submitPending||!text.trim())return;submitInteraction(id=>({type:'user_input',request_id:requestId(),interaction_id:id,text}),text);};
  byId('send-response').addEventListener('click',sendUserResponse);
  byId('user-response').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendUserResponse();}});
  byId('toggle-diagnostics').addEventListener('click',()=>setDiagnosticsOpen(byId('diagnostics-panel').hidden));
  byId('diagnostics').addEventListener('scroll',()=>{if(state.diagnosticsFollow&&byId('diagnostics').scrollTop+byId('diagnostics').clientHeight<byId('diagnostics').scrollHeight-1){state.diagnosticsFollow=false;byId('diagnostics-follow').hidden=false;}});
  byId('diagnostics-follow').addEventListener('click',()=>{state.diagnosticsFollow=true;scrollDiagnosticsToLatest();byId('diagnostics-follow').hidden=true;});
  byId('approve').addEventListener('click',()=>submitInteraction(id=>({type:'confirmation',request_id:requestId(),interaction_id:id,approved:true}),'Approved'));
  byId('reject').addEventListener('click',()=>submitInteraction(id=>({type:'confirmation',request_id:requestId(),interaction_id:id,approved:false}),'Rejected'));
  byId('secret-panel').addEventListener('submit',event=>{event.preventDefault();submitInteraction(id=>{const values={};byId('secret-fields').querySelectorAll('input').forEach(input=>{values[input.name]=input.value;});return{type:'secret',request_id:requestId(),interaction_id:id,values};},'Secure information submitted.');});
  byId('cancel').addEventListener('click',async()=>{if(state.submitPending||!state.runId)return;const selection={runId:state.runId,generation:state.generation};state.submitPending=true;try{render(await api(`runs/${encodeURIComponent(selection.runId)}/cancel`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request_id:requestId()})}),selection);}catch(e){if(state.runId===selection.runId&&state.generation===selection.generation)showError(e.message);}finally{state.submitPending=false;}});
})();"""

OPERATOR_CSS = """:root{color-scheme:dark;--ink:#e8edf2;--muted:#98a4b3;--paper:#090c11;--card:#11161d;--card-raised:#171e27;--accent:#62d6b1;--accent-strong:#20a981;--line:#28313d;--danger:#ef6b73;--focus:#8ee8cd}*{box-sizing:border-box}body{min-height:100vh;margin:0;background:radial-gradient(circle at 15% 0,#172330 0,transparent 34rem),linear-gradient(145deg,#090c11,#0d1219 65%,#101821);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:28px}header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:18px}h1,h2,h3,p{margin-top:0}.eyebrow{color:var(--accent);font-size:.78rem;font-weight:750;letter-spacing:.14em;margin-bottom:4px}.columns{display:grid;grid-template-columns:minmax(0,3fr) minmax(310px,2fr);gap:20px;transition:grid-template-columns .2s ease}.columns.diagnostics-closed{grid-template-columns:minmax(0,1fr)}.column{background:linear-gradient(155deg,rgba(24,31,41,.97),rgba(15,20,27,.98));border:1px solid var(--line);border-radius:16px;box-shadow:0 18px 50px rgba(0,0,0,.24);padding:22px;min-width:0}.start-card{border-bottom:1px solid var(--line);padding-bottom:18px}label{display:block;font-weight:650;margin:10px 0 5px}input,textarea{width:100%;font:inherit;color:var(--ink);background:#0d1218;padding:11px 12px;border:1px solid #354150;border-radius:9px;resize:vertical}input:hover,textarea:hover{border-color:#4b5b6d}input:focus-visible,textarea:focus-visible,button:focus-visible,a:focus-visible{outline:2px solid var(--focus);outline-offset:2px}button{font:inherit;font-weight:700;border:1px solid transparent;border-radius:9px;padding:10px 15px;margin:12px 7px 0 0;background:var(--accent-strong);color:#07130f;cursor:pointer;transition:background .15s ease,transform .15s ease,border-color .15s ease}button:hover:not(:disabled){background:var(--accent);transform:translateY(-1px)}button.secondary{background:#27313d;color:var(--ink);border-color:#3a4655}button.secondary:hover:not(:disabled){background:#344150}button.danger{background:#a83f49;color:#fff}button.danger:hover:not(:disabled){background:#c6505a}button.compact{margin:0;padding:7px 11px;font-size:.84rem}button:disabled{opacity:.45;cursor:not-allowed}.conversation-column{display:flex;flex-direction:column;max-height:calc(100vh - 125px)}#conversation{min-height:120px;flex:1;overflow-y:auto;overscroll-behavior:contain;padding:4px 5px 4px 0}.message{max-width:85%;padding:11px 14px;border:1px solid var(--line);border-radius:13px;margin:14px 0;white-space:pre-wrap;overflow-wrap:anywhere}.message.user{background:#17372f;border-color:#285849;margin-left:auto}.message.agent{background:#202833}.diagnostics{font:13px/1.45 ui-monospace,monospace;max-height:calc(100vh - 125px);display:flex;flex-direction:column}.diagnostics-heading,.run-head{display:flex;align-items:center;justify-content:space-between;gap:10px}.diagnostics ol{padding-left:1.5rem}.diagnostics li{margin:9px 0;overflow-wrap:anywhere}#diagnostics{flex:1;min-height:180px;margin-bottom:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-color:#465467 #11161d}.run-head{padding:9px 11px;background:#0c1117;border:1px solid var(--line);border-radius:9px}.run-head span{overflow-wrap:anywhere}#status{color:var(--accent);background:#16352d;border-radius:999px;padding:2px 8px}#activity{color:var(--muted);margin-top:10px}#error{color:var(--danger);min-height:1.5em}#downloads{padding-left:1.3rem}a{color:var(--accent)}[hidden]{display:none!important}@media(max-width:760px){main{padding:14px}header{align-items:center}.columns{grid-template-columns:1fr}.column,.conversation-column,.diagnostics{max-height:none}#conversation,#diagnostics{max-height:52vh}.message{max-width:92%}}"""
